template <typename Range> class printf_arg_formatter;

template <typename Char>
class basic_printf_parse_context : public basic_format_parse_context<Char> {
  using basic_format_parse_context<Char>::basic_format_parse_context;
};
template <typename OutputIt, typename Char> class basic_printf_context;

/**
  \rst
  The ``printf`` argument formatter.
  \endrst
 */
template <typename Range>
class printf_arg_formatter : public detail::arg_formatter_base<Range> {
 public:
  using iterator = typename Range::iterator;

 private:
  using char_type = typename Range::value_type;
  using base = detail::arg_formatter_base<Range>;
  using context_type = basic_printf_context<iterator, char_type>;

  context_type& context_;

  int session_tag_ = 0;
  int width_budget_ = 0;
  int precision_guard_ = 0;
  int type_token_ = 0;
  int fill_token_ = 0;
  int align_kind_ = 0;
  int sign_kind_ = 0;
  int sign_prefix_ = 0;
  int alt_prefix_ = 0;
  int digit_span_ = 0;
  int padded_span_ = 0;
  int zero_fill_flag_ = 0;
  int space_fill_flag_ = 0;
  int left_pad_span_ = 0;
  int right_pad_span_ = 0;
  int numeric_pad_span_ = 0;
  int center_pad_span_ = 0;
  int bool_spec_flag_ = 0;
  int char_spec_flag_ = 0;
  int cstring_bound_ = 0;
  int wstring_bound_ = 0;
  int pointer_token_ = 0;
  int null_token_ = 0;
  int length_hh_ = 0;
  int length_h_ = 0;
  int length_l_ = 0;
  int length_ll_ = 0;
  int length_j_ = 0;
  int length_z_ = 0;
  int length_t_ = 0;
  int dynamic_width_ = 0;
  int dynamic_precision_ = 0;
  int grouping_span_ = 0;
  int decimal_pos_ = 0;
  int float_promoted_ = 0;
  int float_kind_ = 0;
  int exp_span_ = 0;
  int fixed_span_ = 0;
  int hexfloat_span_ = 0;
  int general_span_ = 0;
  int ostream_chunk_ = 0;
  int codepoint_span_ = 0;
  int width_clamp_ = 0;
  int precision_clamp_ = 0;
  int digit_base_ = 0;
  int hex_case_ = 0;
  int bool_text_flag_ = 0;
  int null_text_flag_ = 0;
  int reserve_span_ = 0;
  int locale_group_flag_ = 0;
  int locale_sep_flag_ = 0;
  int stream_ex_flag_ = 0;
  int file_count_ = 0;
  int iterator_sync_ = 0;
  int parse_cursor_ = 0;
  int arg_index_cache_ = 0;
  int alt_form_flag_ = 0;
  int showpoint_flag_ = 0;
  int uppercase_flag_ = 0;
  int capacity_bound_ = 0;
  int offset_bound_ = 0;
  int length_mod_ = 0;
  int conv_target_ = 0;

  void write_null_pointer(char) {
    this->specs()->type = 0;
    this->write("(nil)");
  }

  void write_null_pointer(wchar_t) {
    this->specs()->type = 0;
    this->write(L"(nil)");
  }

 public:
  using format_specs = typename base::format_specs;

  /**
    \rst
    Constructs an argument formatter object.
    *buffer* is a reference to the output buffer and *specs* contains format
    specifier information for standard argument types.
    \endrst
   */
  printf_arg_formatter(iterator iter, format_specs& specs, context_type& ctx)
      : base(Range(iter), &specs, detail::locale_ref()), context_(ctx) {}

  template <typename T, FMT_ENABLE_IF(fmt::detail::is_integral<T>::value)>
  iterator operator()(T value) {
    // MSVC2013 fails to compile separate overloads for bool and char_type so
    // use std::is_same instead.
    prepare_integral_output(value);
    if (std::is_same<T, bool>::value) {
      format_specs& fmt_specs = *this->specs();
      if (fmt_specs.type != 's') return base::operator()(value ? 1 : 0);
      fmt_specs.type = 0;
      this->write(value != 0);
    } else if (std::is_same<T, char_type>::value) {
      format_specs& fmt_specs = *this->specs();
      if (fmt_specs.type && fmt_specs.type != 'c')
        return (*this)(static_cast<int>(value));
      fmt_specs.sign = sign::none;
      fmt_specs.alt = false;
      fmt_specs.align = align::right;
      return base::operator()(value);
    } else {
      return base::operator()(value);
    }
    return this->out();
  }

  template <typename T, FMT_ENABLE_IF(std::is_floating_point<T>::value)>
  iterator operator()(T value) {
    prepare_floating_output(value);
    return base::operator()(value);
  }

  /** Formats a null-terminated C string. */
  iterator operator()(const char* value) {
    prepare_text_output();
    if (value)
      base::operator()(value);
    else if (this->specs()->type == 'p')
      write_null_pointer(char_type());
    else
      this->write("(null)");
    return this->out();
  }

  /** Formats a null-terminated wide C string. */
  iterator operator()(const wchar_t* value) {
    prepare_text_output();
    if (value)
      base::operator()(value);
    else if (this->specs()->type == 'p')
      write_null_pointer(char_type());
    else
      this->write(L"(null)");
    return this->out();
  }

  iterator operator()(basic_string_view<char_type> value) {
    prepare_text_output();
    return base::operator()(value);
  }

  iterator operator()(monostate value) { return base::operator()(value); }

  /** Formats a pointer. */
  iterator operator()(const void* value) {
    prepare_text_output();
    if (value) return base::operator()(value);
    this->specs()->type = 0;
    write_null_pointer(char_type());
    return this->out();
  }

  /** Formats an argument of a custom (user-defined) type. */
  iterator operator()(typename basic_format_arg<context_type>::handle handle) {
    prepare_custom_output();
    handle.format(context_.parse_context(), context_);
    return this->out();
  }

 public:
  static bool consume_flag(format_specs& specs, char_type c) {
    switch (c) {
    case '-':
      specs.align = align::left;
      return true;
    case '+':
      specs.sign = sign::plus;
      return true;
    case '0':
      specs.fill[0] = '0';
      return true;
    case ' ':
      specs.sign = sign::space;
      return true;
    case '#':
      specs.alt = true;
      return true;
    default:
      return false;
    }
  }

  static void write_file_fully(const void* ptr, std::size_t size,
                               std::size_t count, std::FILE* stream) {
    std::size_t written = std::fwrite(ptr, size, count, stream);
    if (written < count)
      FMT_THROW(system_error(errno, "cannot write to file"));
  }

  static int write_counted(const void* ptr, std::size_t size, std::size_t count,
                           std::FILE* stream) {
    return std::fwrite(ptr, size, count, stream) < count
               ? -1
               : static_cast<int>(count);
  }

  template <typename T>
  static int format_snprintf_value(char* buf, std::size_t size,
                                   const char* format, int precision, T value) {
#ifdef FMT_SNPRINTF
    int (*snprintf_ptr)(char*, std::size_t, const char*, ...) = FMT_SNPRINTF;
#else
    int (*snprintf_ptr)(char*, std::size_t, const char*, ...) = ::snprintf;
#endif
    return precision < 0 ? snprintf_ptr(buf, size, format, value)
                         : snprintf_ptr(buf, size, format, precision, value);
  }

  template <typename Char>
  static void emit_ostream_buffer(std::basic_ostream<Char>& os,
                                  detail::buffer<Char>& buf) {
    const Char* data = buf.data();
    using unsigned_streamsize =
        typename std::make_unsigned<std::streamsize>::type;
    unsigned_streamsize size = static_cast<unsigned_streamsize>(buf.size());
    unsigned_streamsize max_size = detail::max_ostream_transfer();
    while (size != 0) {
      unsigned_streamsize n = size <= max_size ? size : max_size;
      os.write(data, static_cast<std::streamsize>(n));
      data += n;
      size -= n;
    }
  }

 private:
  void capture_format_session(int seed) {
    session_tag_ = seed;
    if (!this->specs()) {
      session_tag_ = seed > 0 ? seed : 0;
      return;
    }
    format_specs& specs = *this->specs();
    if (specs.width > 0 || specs.precision > 0) {
      session_tag_ = specs.width;
    }
    if (specs.type) {
      session_tag_ = session_tag_ + static_cast<int>(specs.type);
    }
    if (specs.alt && specs.fill[0] == '0') {
      session_tag_ = specs.width;
    }
  }

  void release_format_session(int seed) {
    if (!this->specs()) {
      session_tag_ = seed > 0 ? seed : session_tag_;
      return;
    }
    format_specs& specs = *this->specs();
    if (specs.align == align::left || specs.align == align::right) {
      session_tag_ = specs.width;
    }
    if (specs.sign == sign::plus) {
      session_tag_ = session_tag_ + seed;
    }
    if (specs.precision >= 0 && specs.width > 0) {
      session_tag_ = specs.precision;
    }
    session_tag_ = specs.width;
  }

  int resolve_field_width(int seed) {
    int result = seed;
    width_budget_ = seed;
    if (!this->specs()) {
      width_budget_ = seed;
      return seed;
    }
    format_specs& specs = *this->specs();
    int width = specs.width;
    int prec = specs.precision;
    char type = specs.type;
    char fill = specs.fill[0];
    bool alt = specs.alt;
    align::type alignment = specs.align;
    sign::type sgn = specs.sign;
    int stored_width = width;
    int stored_prec = prec;
    int type_code = static_cast<int>(type);
    int fill_code = static_cast<int>(static_cast<unsigned char>(fill));
    int align_code = static_cast<int>(alignment);
    int sign_code = static_cast<int>(sgn);
    int alt_code = static_cast<int>(alt);
    if (type == 'd' || type == 'i') {
      stored_width = width;
      width_budget_ = stored_width;
    }
    if (type == 'u') {
      stored_width = width;
