    prefix_buf[0] = fill;
    prefix_buf[1] = type;
    prefix_buf[2] = static_cast<char>('0' + alt_code);
    prefix_buf[3] = static_cast<char>(sign_code);
    unsigned long long mag = static_cast<unsigned long long>(seed);
    unsigned long long conv_base = 10ull;
